import numpy as np


class RefinedExpandPolishDebES:
    """Deb feasibility-rule (mu+lambda) mixed-variable ES. Operators: (0) Cauchy-tailed ES
    mutation with crossover, (1) DE current-to-anchor, (2) light anchor mutation,
    (3) boundary bisection toward the feasible anchor, (4) archive-directed moves.
    Operators are chosen by a budget-decaying credit floor; step sizes adapt by a 1/5th rule.
    Polishing uses coordinate line search with step expansion on success, a random-direction
    probe and extrapolation, and runs immediately whenever the feasible best improves."""

    def __init__(self, budget=10000, dim=10):
        self.budget = int(budget)
        self.dim = int(dim)

    def __call__(self, func):
        dim = self.dim
        lb = np.asarray(func.bounds.lb, dtype=float)
        ub = np.asarray(func.bounds.ub, dtype=float)
        span = ub - lb
        vtypes = [str(t) for t in func.variable_types]
        is_int = np.array([vt != "continuous" for vt in vtypes], dtype=bool)
        int_idx = np.where(is_int)[0]
        cont_idx = np.where(~is_int)[0]
        nv = np.zeros(dim, dtype=int)
        for i in int_idx:
            nv[i] = int(func.n_values[i])

        def fix(x):
            x = np.array(x, dtype=float)
            if len(int_idx):
                x[int_idx] = np.clip(np.round(x[int_idx]), 0, nv[int_idx] - 1)
            if len(cont_idx):
                x[cont_idx] = np.clip(x[cont_idx], lb[cont_idx], ub[cont_idx])
            return x

        def sample():
            return fix(lb + np.random.random(dim) * span)

        def lhs(n):
            pts = np.empty((n, dim))
            for d in range(dim):
                perm = np.random.permutation(n)
                pts[:, d] = (perm + np.random.random(n)) / n
            return [fix(lb + u * span) for u in pts]

        def key(ind):
            return (0, ind[1]) if ind[2] == 0 else (1, ind[2])

        used = 0
        inc = None
        best_feas = None
        cache = {}
        archive = []
        vs = np.ones(dim)
        h_store = np.full(dim, 0.05)

        def arch_add(ind):
            nonlocal archive
            archive.append(ind)
            archive.sort(key=lambda z: z[1])
            kept = []
            for z in archive:
                ok = True
                for w in kept:
                    d = np.linalg.norm((z[0] - w[0]) / np.maximum(span, 1e-12))
                    if d < 1e-3:
                        ok = False
                        break
                if ok:
                    kept.append(z)
                if len(kept) >= 30:
                    break
            archive = kept

        def ev(x):
            nonlocal used, inc, best_feas
            x = fix(x)
            k = x.tobytes()
            if k in cache:
                return cache[k]
            if used >= self.budget:
                return None
            used += 1
            f, g = func(x)
            f = float(f)
            g = np.nan_to_num(np.asarray(g, dtype=float).ravel(),
                              nan=1e6, posinf=1e6, neginf=0.0)
            v = float(np.sum(np.maximum(g, 0.0)))
            if not np.isfinite(f):
                f = 1e30
                v += 1.0
            ind = (x, f, v)
            cache[k] = ind
            if inc is None or key(ind) < key(inc):
                inc = ind
            if v == 0:
                arch_add(ind)
                if best_feas is None or f < best_feas[1]:
                    best_feas = ind
            return ind

        def anchor():
            return best_feas if best_feas is not None else inc

        def tour(pop):
            a = pop[np.random.randint(len(pop))]
            b = pop[np.random.randint(len(pop))]
            return a if key(a) <= key(b) else b

        def crossover(a, b):
            m = np.random.random(dim) < 0.5
            return np.where(m, a, b)

        def mutate(x, pm, sig, heavy=0.0):
            y = x.copy()
            mask = np.random.random(dim) < pm
            if not mask.any():
                mask[np.random.randint(dim)] = True
            for i in np.nonzero(mask)[0]:
                if is_int[i]:
                    n = nv[i]
                    if n <= 1:
                        continue
                    cur = int(round(y[i]))
                    if n == 2 or vtypes[i] == "binary":
                        y[i] = 1 - cur
                    elif vtypes[i] == "ordinal" and np.random.random() < 0.6:
                        step = 1 if np.random.random() < 0.5 else -1
                        nxt = cur + step
                        if nxt < 0 or nxt > n - 1:
                            nxt = cur - step
                        y[i] = nxt
                    else:
                        r = np.random.randint(n - 1)
                        if r >= cur:
                            r += 1
                        y[i] = r
                else:
                    if heavy > 0 and np.random.random() < heavy:
                        step = float(np.clip(np.random.standard_cauchy(), -5.0, 5.0))
                    else:
                        step = np.random.normal()
                    y[i] += sig * vs[i] * span[i] * step
            return fix(y)

        def de_move(base, a, b, c, F, cr):
            y = base.copy()
            mask = np.random.random(dim) < cr
            if not mask.any():
                mask[np.random.randint(dim)] = True
            for i in np.nonzero(mask)[0]:
                if is_int[i]:
                    y[i] = a[i] if np.random.random() < 0.5 else c[i]
                else:
                    y[i] = base[i] + F * (a[i] - b[i]) + 0.5 * F * (c[i] - base[i])
            return fix(y)

        def bisect_move(c_ind, a_ind, steps=3):
            out = []
            a = a_ind[0]
            c = c_ind[0]
            lo, hi = 0.0, 1.0
            for _ in range(steps):
                mid = 0.5 * (lo + hi)
                ind = ev(a + mid * (c - a))
                if ind is None:
                    break
                out.append(ind)
                if ind[2] == 0:
                    lo = mid
                else:
                    hi = mid
            return out

        def directed_move(best, scale):
            if len(archive) >= 3:
                if np.random.random() < 0.5:
                    i1, i2 = np.random.choice(len(archive), 2, replace=False)
                    d = archive[i1][0] - archive[i2][0]
                else:
                    j = np.random.randint(len(archive))
                    d = archive[j][0] - best[0]
                    d = -d * np.random.uniform(0.0, 1.0)
            else:
                d = np.random.normal(size=dim) * span * 0.05
            y = best[0].copy()
            F = scale * np.random.uniform(0.3, 1.0)
            for i in cont_idx:
                y[i] += F * d[i]
            if len(archive) > 0 and len(int_idx):
                donor = archive[np.random.randint(len(archive))][0]
                m = np.random.random(len(int_idx)) < 0.25
                sel = int_idx[m]
                y[sel] = donor[sel]
            return fix(y)

        def local_search(ind, max_evals):
            cur = ind
            prev = None
            h = h_store
            n0 = used
            while used - n0 < max_evals and used < self.budget:
                improved = False
                if prev is not None and used - n0 < max_evals and used < self.budget:
                    x = fix(cur[0] + 0.5 * (cur[0] - prev[0]))
                    c = ev(x)
                    if c is not None and key(c) < key(cur):
                        prev, cur = cur, c
                        improved = True
                # random-direction probe over continuous coordinates
                if len(cont_idx) > 0 and used - n0 < max_evals and used < self.budget:
                    d = np.random.normal(size=len(cont_idx))
                    d /= (np.linalg.norm(d) + 1e-12)
                    x = cur[0].copy()
                    x[cont_idx] += np.mean(h[cont_idx]) * span[cont_idx] * d * np.sqrt(len(cont_idx))
                    c = ev(x)
                    if c is not None and key(c) < key(cur):
                        prev, cur = cur, c
                        improved = True
                # coordinate line search with pattern expansion on success
                for i in np.random.permutation(cont_idx):
                    moved = False
                    for s in (1.0, -1.0):
                        if used - n0 >= max_evals or used >= self.budget:
                            break
                        x = cur[0].copy()
                        x[i] += s * h[i] * span[i]
                        c = ev(x)
                        if c is not None and key(c) < key(cur):
                            prev, cur = cur, c
                            improved = True
                            moved = True
                            # expand along the successful direction while it keeps improving
                            step = h[i]
                            for _ in range(4):
                                if used - n0 >= max_evals or used >= self.budget:
                                    break
                                step *= 2.0
                                x2 = cur[0].copy()
                                x2[i] += s * step * span[i]
                                c2 = ev(x2)
                                if c2 is not None and key(c2) < key(cur):
                                    prev, cur = cur, c2
                                else:
                                    break
                            h[i] = min(step * 0.5 if step > h[i] else h[i] * 2.0, 0.5)
                            break
                    if not moved:
                        h[i] = max(h[i] * 0.7, 1e-5)
                for i in int_idx:
                    if used - n0 >= max_evals or used >= self.budget:
                        break
                    n = nv[i]
                    if n <= 1:
                        continue
                    cv = int(round(cur[0][i]))
                    cand_vals = [v for v in range(n) if v != cv]
                    val = cand_vals[np.random.randint(len(cand_vals))]
                    x = cur[0].copy()
                    x[i] = val
                    c = ev(x)
                    if c is not None and key(c) < key(cur):
                        prev, cur = cur, c
                        improved = True
                if not improved:
                    h *= 0.5
                    if h.max() < 1e-4:
                        h[:] = np.maximum(h, 0.02)
                        break
            return cur

        def update_vs():
            nonlocal vs
            if len(cont_idx) == 0:
                return
            r = np.ones(dim)
            r[cont_idx] = np.clip(h_store[cont_idx] / 0.05, 1e-3, 1e3)
            lr = np.log(r[cont_idx])
            r[cont_idx] = np.exp(lr - lr.mean())
            vs = 0.5 * vs + 0.5 * np.clip(r, 0.2, 5.0)

        def archive_spread():
            if len(archive) < 3 or len(cont_idx) == 0:
                return 0.1
            X = np.array([z[0] for z in archive])[:, cont_idx]
            sd = X.std(axis=0) / np.maximum(span[cont_idx], 1e-12)
            return float(np.clip(np.mean(sd), 0.005, 0.5))

        # ---- parameters ----
        mu = int(np.clip(min(4 * dim, self.budget // 10), 6, 40))
        lam = 2 * mu
        n_ops = 5
        sig_es = 0.2
        sig_anc = 0.2
        sig_diff = 0.5
        p_heavy = 0.1
        credit = np.full(n_ops, 0.2)
        polished_f = np.inf

        pool = []
        for ind_x in lhs(2 * mu):
            ind = ev(ind_x)
            if ind is None:
                break
            pool.append(ind)
        if not pool:
            if inc is None:
                return np.inf, None
            return (inc[1] if inc[2] == 0 else np.inf), inc[0]
        pool.sort(key=key)
        pop = pool[:mu]

        gen = 0
        stagn = 0
        restarts = 0
        pert_count = 0
        last_key = key(inc)

        while used < self.budget:
            floor = max(0.03, 0.08 * (1.0 - used / self.budget))
            probs = np.maximum(credit, floor)
            if best_feas is None:
                probs[3] = max(probs[3], 0.3)
            probs = probs / probs.sum()
            children = []
            trials = np.zeros(n_ops)
            succ = np.zeros(n_ops)
            succ_heavy = 0
            n_heavy = 0
            prev_best_f = best_feas[1] if best_feas is not None else np.inf

            for _ in range(lam):
                if used >= self.budget:
                    break
                op = int(np.random.choice(n_ops, p=probs))
                hf = False
                if op == 0 or (len(pop) < 3 and op == 1):
                    p1 = tour(pop)
                    p2 = tour(pop)
                    if np.random.random() < 0.6:
                        child = crossover(p1[0], p2[0])
                    else:
                        child = p1[0].copy()
                    pm = np.exp(np.random.uniform(np.log(1.0 / dim), np.log(0.5)))
                    hf = np.random.random() < p_heavy
                    child = mutate(child, pm, sig_es, heavy=(1.0 if hf else 0.0))
                    ind = ev(child)
                    if ind is None:
                        break
                    if hf:
                        n_heavy += 1
                    children.append((ind, 0, hf))
                elif op == 1:
                    idx = np.random.choice(len(pop), 3, replace=False)
                    base = anchor()
                    if base is None:
                        base = pop[0]
                    F = np.random.uniform(0.4, 0.9)
                    cr = np.random.uniform(0.3, 0.9)
                    child = de_move(base[0], pop[idx[0]][0], pop[idx[1]][0],
                                    pop[idx[2]][0], F, cr)
                    child = mutate(child, 1.0 / dim, sig_anc * 0.5)
                    ind = ev(child)
                    if ind is None:
                        break
                    children.append((ind, 1, False))
                elif op == 2:
                    base = anchor()
                    if base is None:
                        base = tour(pop)
                    child = mutate(base[0], 2.0 / dim, sig_anc)
                    ind = ev(child)
                    if ind is None:
                        break
                    children.append((ind, 2, False))
                elif op == 3:
                    infeas = [p for p in pop if p[2] > 0]
                    if best_feas is None or not infeas:
                        ind = ev(mutate(tour(pop)[0], 0.5, sig_es))
                        if ind is None:
                            break
                        children.append((ind, 3, False))
                    else:
                        src = infeas[np.random.randint(len(infeas))]
                        ind = ev(mutate(src[0], 0.5, sig_anc))
                        if ind is None:
                            break
                        children.append((ind, 3, False))
                        if ind[2] > 0:
                            for b in bisect_move(ind, best_feas):
                                children.append((b, 3, False))
                else:
                    base = anchor()
                    if base is None or len(pop) < 2:
                        ind = ev(sample())
                    else:
                        ind = ev(directed_move(base, sig_diff))
                    if ind is None:
                        break
                    children.append((ind, 4, False))

            if not children:
                break

            combined = pop + [c[0] for c in children]
            combined.sort(key=key)
            survivors = combined[:mu]
            surv_ids = {id(s) for s in survivors}
            for c, op, hf in children:
                trials[op] += 1
                if id(c) in surv_ids:
                    succ[op] += 1
                    if op == 0 and hf:
                        succ_heavy += 1

            if trials[0] > 0:
                r0 = succ[0] / trials[0]
                sig_es *= 1.22 if r0 > 0.2 else 0.82
                sig_es = float(np.clip(sig_es, 1e-4, 0.5))
            if trials[2] > 0:
                r2 = succ[2] / trials[2]
                sig_anc *= 1.22 if r2 > 0.2 else 0.82
                sig_anc = float(np.clip(sig_anc, 1e-4, 0.5))
            if trials[4] > 0:
                r4 = succ[4] / trials[4]
                sig_diff *= 1.15 if r4 > 0.2 else 0.85
                sig_diff = float(np.clip(sig_diff, 0.02, 1.5))

            rate0 = succ[0] / max(trials[0], 1)
            if n_heavy >= 3:
                hr = succ_heavy / n_heavy
                p_heavy = float(np.clip(p_heavy * (1.1 if hr > rate0 else 0.9), 0.02, 0.4))

            for o in range(n_ops):
                if trials[o] > 0:
                    credit[o] = 0.7 * credit[o] + 0.3 * (succ[o] / trials[o])

            pop = survivors
            gen += 1

            cur_key = key(inc)
            if cur_key < last_key:
                last_key = cur_key
                stagn = 0
                for c, op, hf in children:
                    if c is inc:
                        bonus = 0.1
                        if best_feas is not None and c is best_feas and prev_best_f < np.inf:
                            rel = (prev_best_f - c[1]) / (abs(prev_best_f) + 1e-12)
                            bonus += 0.25 * float(np.clip(rel, 0.0, 1.0))
                        credit[op] += bonus
            else:
                stagn += 1

            # immediate polishing whenever the feasible best improves;
            # larger budget early on, when anytime gains matter most
            if best_feas is not None and best_feas[1] < polished_f - 1e-12 and used < self.budget:
                polished_f = best_feas[1]
                frac = used / self.budget
                pol_budget = (4 * dim + 8) if frac < 0.3 else (2 * dim + 4)
                ls = local_search(best_feas, max_evals=pol_budget)
                if ls[2] == 0 and ls[1] < polished_f - 1e-12:
                    polished_f = ls[1]
                pop.sort(key=key)
                if key(ls) < key(pop[-1]):
                    pop[-1] = ls
                pop.sort(key=key)
                update_vs()

            improving = stagn <= 2
            polish_period = 3 if improving else (6 if stagn > 5 else 8)
            if gen % polish_period == 0 and inc is not None and used < self.budget:
                base = anchor()
                best_ls = local_search(base, max_evals=4 * dim + 8)
                update_vs()
                pop.sort(key=key)
                if key(best_ls) < key(pop[-1]):
                    pop[-1] = best_ls
                pop.sort(key=key)

            if stagn >= 15 and used < self.budget:
                restarts += 1
                elites = pop[:2]
                newpop = list(elites)
                base_ind = anchor()
                perturb = (restarts % 3 != 0) and base_ind is not None
                if perturb:
                    pert_count += 1
                spread = archive_spread()
                pscale = max(0.003, min(0.3 * (0.75 ** pert_count), spread))
                seed = base_ind
                if len(archive) > 1 and np.random.random() < 0.5:
                    seed = archive[np.random.randint(len(archive))]
                for j in range(mu - len(elites)):
                    if perturb and seed is not None:
                        ind = ev(mutate(seed[0], 0.3, pscale, heavy=0.2))
                    else:
                        ind = ev(sample())
                    if ind is None:
                        break
                    newpop.append(ind)
                if len(newpop) >= 2:
                    pop = newpop
                    pop.sort(key=key)
                sig_es = 0.1 if perturb else 0.2
                sig_anc = 0.1 if perturb else 0.2
                sig_diff = 0.3 if perturb else 0.5
                credit = 0.5 * credit + 0.1
                stagn = 0

        if best_feas is not None:
            return best_feas[1], best_feas[0]
        if inc is None:
            return np.inf, None
        return np.inf, inc[0]
